package snippets.java.cache;

import java.util.*;

/**
 * LRU Cache Implementations in Java
 */
public class LRUCache {

    // ---- Implementation 1: LinkedHashMap (simplest) ----
    static class LRULinkedHashMap<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;
        LRULinkedHashMap(int capacity) { super(capacity, 0.75f, true); this.capacity = capacity; }
        @Override protected boolean removeEldestEntry(Map.Entry<K,V> eldest) { return size() > capacity; }
    }

    // ---- Implementation 2: Doubly Linked List + HashMap ----
    static class LRUCacheCustom {
        private static class Node {
            int key, val; Node prev, next;
            Node(int k, int v) { key=k; val=v; }
        }
        private final int cap;
        private final Map<Integer, Node> map;
        private final Node head, tail; // sentinels

        LRUCacheCustom(int capacity) {
            cap = capacity;
            map = new HashMap<>();
            head = new Node(0,0); tail = new Node(0,0);
            head.next = tail; tail.prev = head;
        }

        public int get(int key) {
            if (!map.containsKey(key)) return -1;
            Node node = map.get(key);
            remove(node); insertFront(node); // move to front
            return node.val;
        }

        public void put(int key, int value) {
            if (map.containsKey(key)) remove(map.get(key));
            if (map.size() == cap) remove(tail.prev); // evict LRU
            insertFront(new Node(key, value));
        }

        private void remove(Node n) {
            map.remove(n.key);
            n.prev.next = n.next; n.next.prev = n.prev;
        }

        private void insertFront(Node n) {
            map.put(n.key, n);
            n.next = head.next; n.prev = head;
            head.next.prev = n; head.next = n;
        }
    }

    // ---- LFU Cache (Least Frequently Used) ----
    static class LFUCache {
        private final int cap;
        private int minFreq;
        private final Map<Integer, Integer> keyVal, keyFreq;
        private final Map<Integer, LinkedHashSet<Integer>> freqKeys;

        LFUCache(int capacity) {
            cap = capacity; minFreq = 0;
            keyVal = new HashMap<>(); keyFreq = new HashMap<>(); freqKeys = new HashMap<>();
        }

        public int get(int key) {
            if (!keyVal.containsKey(key)) return -1;
            updateFreq(key); return keyVal.get(key);
        }

        public void put(int key, int value) {
            if (cap == 0) return;
            if (keyVal.containsKey(key)) { keyVal.put(key, value); updateFreq(key); return; }
            if (keyVal.size() == cap) {
                LinkedHashSet<Integer> minSet = freqKeys.get(minFreq);
                int evict = minSet.iterator().next(); minSet.remove(evict);
                keyVal.remove(evict); keyFreq.remove(evict);
            }
            keyVal.put(key, value); keyFreq.put(key, 1);
            freqKeys.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
            minFreq = 1;
        }

        private void updateFreq(int key) {
            int f = keyFreq.get(key);
            keyFreq.put(key, f+1);
            freqKeys.get(f).remove(key);
            if (freqKeys.get(f).isEmpty() && f == minFreq) minFreq++;
            freqKeys.computeIfAbsent(f+1, k -> new LinkedHashSet<>()).add(key);
        }
    }

    public static void main(String[] args) {
        // LinkedHashMap LRU
        LRULinkedHashMap<Integer, String> lhm = new LRULinkedHashMap<>(3);
        lhm.put(1,"a"); lhm.put(2,"b"); lhm.put(3,"c");
        lhm.get(1);   // access 1 → now MRU
        lhm.put(4,"d"); // 2 should be evicted
        System.out.println(lhm.containsKey(2)); // false

        // Custom LRU
        LRUCacheCustom cache = new LRUCacheCustom(2);
        cache.put(1,1); cache.put(2,2);
        System.out.println(cache.get(1));  // 1
        cache.put(3,3); // 2 evicted
        System.out.println(cache.get(2));  // -1
    }
}

package snippets.java.patterns;

import java.util.HashMap;
import java.util.Map;

/**
 * Creational Design Patterns in Java
 */
public class CreationalPatterns {

    // ---- 1. Singleton (Thread-safe, Lazy) ----
    static class Singleton {
        private static volatile Singleton instance;
        private int value;
        private Singleton() { value = 42; }
        public static Singleton getInstance() {
            if (instance == null) {
                synchronized (Singleton.class) {
                    if (instance == null) instance = new Singleton(); // DCL
                }
            }
            return instance;
        }
        // Or better: Holder pattern (JVM-level thread-safety)
        private static class Holder { static final Singleton INSTANCE = new Singleton(); }
        public static Singleton holderInstance() { return Holder.INSTANCE; }
    }

    // ---- 2. Builder ----
    static class HttpRequest {
        private final String url;
        private final String method;
        private final Map<String, String> headers;
        private final String body;
        private final int timeoutMs;

        private HttpRequest(Builder b) {
            url = b.url; method = b.method; headers = b.headers; body = b.body; timeoutMs = b.timeoutMs;
        }

        static class Builder {
            private final String url;
            private String method = "GET";
            private Map<String, String> headers = new HashMap<>();
            private String body;
            private int timeoutMs = 5000;
            Builder(String url) { this.url = url; }
            Builder method(String m) { this.method = m; return this; }
            Builder header(String k, String v) { headers.put(k, v); return this; }
            Builder body(String b) { this.body = b; return this; }
            Builder timeout(int ms) { this.timeoutMs = ms; return this; }
            HttpRequest build() {
                if (url == null || url.isBlank()) throw new IllegalStateException("URL required");
                return new HttpRequest(this);
            }
        }
        @Override public String toString() { return method + " " + url; }
    }

    // ---- 3. Factory Method ----
    interface Notification { void send(String message); }
    static class EmailNotification implements Notification { public void send(String m){ System.out.println("Email: " + m); } }
    static class SMSNotification   implements Notification { public void send(String m){ System.out.println("SMS: " + m); } }
    static class PushNotification   implements Notification { public void send(String m){ System.out.println("Push: " + m); } }

    static Notification notificationFactory(String type) {
        return switch (type.toLowerCase()) {
            case "email" -> new EmailNotification();
            case "sms"   -> new SMSNotification();
            case "push"  -> new PushNotification();
            default -> throw new IllegalArgumentException("Unknown type: " + type);
        };
    }

    // ---- 4. Abstract Factory ----
    interface Button { void render(); }
    interface Checkbox { void render(); }
    interface UIFactory { Button createButton(); Checkbox createCheckbox(); }

    static class WindowsButton implements Button { public void render(){ System.out.println("Windows Button"); } }
    static class WindowsCheckbox implements Checkbox { public void render(){ System.out.println("Windows Checkbox"); } }
    static class MacButton implements Button { public void render(){ System.out.println("Mac Button"); } }
    static class MacCheckbox implements Checkbox { public void render(){ System.out.println("Mac Checkbox"); } }

    static class WindowsFactory implements UIFactory {
        public Button createButton() { return new WindowsButton(); }
        public Checkbox createCheckbox() { return new WindowsCheckbox(); }
    }
    static class MacFactory implements UIFactory {
        public Button createButton() { return new MacButton(); }
        public Checkbox createCheckbox() { return new MacCheckbox(); }
    }

    // ---- 5. Prototype ----
    static class Config implements Cloneable {
        Map<String, String> settings;
        Config(Map<String, String> s) { settings = new HashMap<>(s); }
        @Override public Config clone() {
            try { Config copy = (Config) super.clone(); copy.settings = new HashMap<>(settings); return copy; }
            catch (CloneNotSupportedException e) { throw new RuntimeException(e); }
        }
    }

    public static void main(String[] args) {
        // Singleton
        Singleton s1 = Singleton.getInstance();
        Singleton s2 = Singleton.getInstance();
        System.out.println(s1 == s2); // true

        // Builder
        HttpRequest req = new HttpRequest.Builder("https://api.example.com/users")
            .method("POST")
            .header("Content-Type", "application/json")
            .body("{\"name\":\"Alice\"}")
            .timeout(3000)
            .build();
        System.out.println(req);

        // Factory
        notificationFactory("email").send("Hello!");
        notificationFactory("sms").send("Hello!");

        // Abstract Factory
        UIFactory factory = new MacFactory();
        factory.createButton().render();
        factory.createCheckbox().render();
    }
}

package snippets.java.spring;

import org.springframework.cache.annotation.*;
import org.springframework.scheduling.annotation.*;
import org.springframework.stereotype.*;
import org.springframework.transaction.annotation.*;
import java.util.List;
import java.util.concurrent.CompletableFuture;

/**
 * Spring Boot Performance Patterns
 */
public class PerformanceTuning {

    // 1. Caching with Spring Cache (@Cacheable, @CacheEvict)
    @Service
    static class ProductService {
        @Cacheable(value = "products", key = "#id")
        public Product findById(Long id) {
            // Expensive DB call — cached after first invocation
            return fetchFromDB(id);
        }

        @CacheEvict(value = "products", key = "#product.id")
        public Product update(Product product) {
            // Clears cache on update
            return saveToDb(product);
        }

        @CachePut(value = "products", key = "#result.id")
        public Product create(Product product) {
            // Updates cache after insert
            return saveToDb(product);
        }

        @CacheEvict(value = "products", allEntries = true)
        @Scheduled(fixedDelay = 3600000) // every hour
        public void evictAllCaches() { /* cache warm periodically */ }

        private Product fetchFromDB(Long id) { return new Product(); }
        private Product saveToDb(Product p) { return p; }
    }

    // 2. Async methods
    @Service
    static class AsyncService {
        @Async("taskExecutor") // use custom thread pool
        public CompletableFuture<String> asyncFetch(Long id) {
            // Runs in thread pool, doesn't block HTTP thread
            String result = "result-" + id;
            return CompletableFuture.completedFuture(result);
        }
    }

    // 3. Pagination to avoid N+1 and large result sets
    @org.springframework.data.jpa.repository.JpaRepository
    interface OrderRepo extends org.springframework.data.jpa.repository.JpaRepository<Object, Long> {}

    // 4. Read-only transactions (skip dirty checking overhead)
    @Service
    static class ReadService {
        @Transactional(readOnly = true)
        public List<Object> getAll() { return List.of(); }

        // Batch inserts — avoid N single inserts
        @Transactional
        public void batchInsert(List<Object> items) {
            // spring.jpa.properties.hibernate.jdbc.batch_size=50
            // spring.jpa.properties.hibernate.order_inserts=true
        }
    }

    // 5. Projections — fetch only needed columns
    interface UserSummary {
        Long getId();
        String getName();
        // Only 2 columns fetched, not entire entity
    }

    // 6. Connection pool tuning (HikariCP — Spring Boot default)
    // application.properties:
    // spring.datasource.hikari.maximum-pool-size=20
    // spring.datasource.hikari.minimum-idle=5
    // spring.datasource.hikari.connection-timeout=20000
    // spring.datasource.hikari.idle-timeout=300000
    // spring.datasource.hikari.max-lifetime=1200000

    // 7. Lazy loading for related entities
    @jakarta.persistence.Entity
    static class Product {
        @jakarta.persistence.Id Long id;
        String name;
        // @OneToMany(fetch = FetchType.LAZY) — default, don't change to EAGER
        // Use JOIN FETCH in JPQL when you need the collection
    }

    // JVM Tuning flags (add to JVM args):
    // -Xms512m -Xmx2g              → initial/max heap
    // -XX:+UseG1GC                 → G1 garbage collector (default Java 9+)
    // -XX:MaxGCPauseMillis=200     → target max GC pause
    // -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/tmp/heap.hprof
}

package snippets.java.nio;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.*;
import java.nio.channels.*;
import java.util.Iterator;

/**
 * Java NIO — Non-blocking Server
 * Selector allows one thread to handle multiple connections.
 */
public class NonBlockingServer {

    public static void startServer(int port) throws IOException {
        Selector selector = Selector.open();
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.bind(new InetSocketAddress(port));
        serverChannel.configureBlocking(false);
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);
        System.out.println("Server started on port " + port);

        while (true) {
            selector.select(); // blocks until events are ready
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();
                keys.remove();
                try {
                    if (key.isAcceptable()) handleAccept(selector, key);
                    else if (key.isReadable()) handleRead(key);
                } catch (IOException e) {
                    key.cancel();
                    key.channel().close();
                }
            }
        }
    }

    private static void handleAccept(Selector selector, SelectionKey key) throws IOException {
        ServerSocketChannel server = (ServerSocketChannel) key.channel();
        SocketChannel client = server.accept();
        client.configureBlocking(false);
        client.register(selector, SelectionKey.OP_READ, ByteBuffer.allocate(1024));
        System.out.println("Accepted: " + client.getRemoteAddress());
    }

    private static void handleRead(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = (ByteBuffer) key.attachment();
        buffer.clear();
        int bytesRead = client.read(buffer);
        if (bytesRead == -1) { client.close(); return; }
        buffer.flip();
        byte[] data = new byte[buffer.limit()];
        buffer.get(data);
        String message = new String(data).trim();
        System.out.println("Received: " + message);
        // Echo back
        buffer.rewind();
        client.write(buffer);
    }

    // ---- FileChannel — file copy ----
    public static void fastCopy(String src, String dst) throws IOException {
        try (FileChannel in  = FileChannel.open(java.nio.file.Path.of(src), java.nio.file.StandardOpenOption.READ);
             FileChannel out = FileChannel.open(java.nio.file.Path.of(dst),
                     java.nio.file.StandardOpenOption.WRITE, java.nio.file.StandardOpenOption.CREATE)) {
            in.transferTo(0, in.size(), out); // zero-copy OS call
        }
    }

    // ---- Memory-mapped file ----
    public static void memoryMap(String filePath) throws IOException {
        try (FileChannel channel = FileChannel.open(java.nio.file.Path.of(filePath),
                java.nio.file.StandardOpenOption.READ)) {
            MappedByteBuffer buffer = channel.map(FileChannel.MapMode.READ_ONLY, 0, channel.size());
            // Buffer is directly mapped to OS memory — no extra copy
            byte firstByte = buffer.get(0); // OS page fault on first access
            System.out.println("First byte: " + firstByte);
        }
    }

    public static void main(String[] args) throws Exception {
        // Start in background thread
        new Thread(() -> { try { startServer(8080); } catch (IOException e) { e.printStackTrace(); } }).start();
        Thread.sleep(100);
        System.out.println("Server is running. Connect on port 8080.");
    }
}

package snippets.java.spring;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.*;
import org.springframework.stereotype.Component;
import java.lang.annotation.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Spring AOP — Java's Answer to Decorators/Middleware
 */
@Aspect
@Component
public class AspectPatterns {

    // ---- Custom Annotation ----
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    public @interface Loggable { String level() default "INFO"; }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    public @interface Cacheable { int ttlSeconds() default 60; }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    public @interface RateLimit { int rpm() default 100; }

    // ---- Logging Aspect ----
    @Around("@annotation(snippets.java.spring.AspectPatterns.Loggable)")
    public Object logExecution(ProceedingJoinPoint pjp) throws Throwable {
        long start = System.currentTimeMillis();
        String method = pjp.getSignature().toShortString();
        System.out.println("→ Entering: " + method);
        try {
            Object result = pjp.proceed();
            System.out.printf("← Exiting: %s (took %dms)%n", method, System.currentTimeMillis()-start);
            return result;
        } catch (Throwable ex) {
            System.out.println("✗ Exception in " + method + ": " + ex.getMessage());
            throw ex;
        }
    }

    // ---- Caching Aspect ----
    private final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    @Around("@annotation(snippets.java.spring.AspectPatterns.Cacheable)")
    public Object cacheResult(ProceedingJoinPoint pjp) throws Throwable {
        String key = pjp.getSignature().toLongString() + java.util.Arrays.toString(pjp.getArgs());
        if (cache.containsKey(key)) {
            System.out.println("Cache hit: " + key);
            return cache.get(key);
        }
        Object result = pjp.proceed();
        cache.put(key, result);
        return result;
    }

    // ---- Transaction Aspect (simplified) ----
    @Around("@annotation(org.springframework.transaction.annotation.Transactional)")
    public Object manageTransaction(ProceedingJoinPoint pjp) throws Throwable {
        System.out.println("BEGIN TRANSACTION");
        try {
            Object result = pjp.proceed();
            System.out.println("COMMIT");
            return result;
        } catch (Exception e) {
            System.out.println("ROLLBACK");
            throw e;
        }
    }

    // ---- @Before, @After, @AfterThrowing ----
    @Before("execution(* snippets.java.spring..*Service.*(..))")  // all service methods
    public void beforeServiceCall(org.aspectj.lang.JoinPoint jp) {
        System.out.println("Security check before: " + jp.getSignature().getName());
    }

    @AfterThrowing(pointcut = "execution(* snippets.java.spring..*(..))", throwing = "ex")
    public void afterException(Exception ex) {
        System.err.println("Exception caught by aspect: " + ex.getMessage());
    }

    // ---- Usage Example ----
    @Component
    static class UserService {
        @Loggable
        @Cacheable(ttlSeconds = 300)
        public String getUser(Long id) {
            // method body — automatically logged + cached by aspects
            return "User-" + id;
        }
    }
}

package snippets.java.db;

import com.zaxxer.hikari.*;
import java.sql.*;
import java.util.*;

/**
 * Java JDBC + HikariCP Connection Pool Patterns
 */
public class JdbcPatterns {

    // ---- HikariCP Setup ----
    public static HikariDataSource createPool() {
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl("jdbc:postgresql://localhost:5432/mydb");
        config.setUsername("dbuser");
        config.setPassword(System.getenv("DB_PASS"));
        config.setMaximumPoolSize(20);
        config.setMinimumIdle(5);
        config.setConnectionTimeout(20_000);
        config.setIdleTimeout(300_000);
        config.setMaxLifetime(1_200_000);
        config.addDataSourceProperty("cachePrepStmts", "true");
        config.addDataSourceProperty("prepStmtCacheSize", "250");
        return new HikariDataSource(config);
    }

    // ---- CRUD with PreparedStatement ----
    private final HikariDataSource ds;
    JdbcPatterns(HikariDataSource ds) { this.ds = ds; }

    public Optional<User> findById(long id) {
        String sql = "SELECT id, name, email FROM users WHERE id = ?";
        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setLong(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return Optional.of(mapRow(rs));
                return Optional.empty();
            }
        } catch (SQLException e) {
            throw new RuntimeException("DB error", e);
        }
    }

    public void insertBatch(List<User> users) {
        String sql = "INSERT INTO users (name, email) VALUES (?, ?)";
        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            conn.setAutoCommit(false);
            for (User u : users) {
                ps.setString(1, u.name);
                ps.setString(2, u.email);
                ps.addBatch();  // accumulate
            }
            ps.executeBatch();  // single round-trip to DB
            conn.commit();
        } catch (SQLException e) {
            throw new RuntimeException("Batch insert failed", e);
        }
    }

    public void executeInTransaction(Runnable work) {
        try (Connection conn = ds.getConnection()) {
            conn.setAutoCommit(false);
            Savepoint sp = conn.setSavepoint("before");
            try {
                work.run();
                conn.commit();
            } catch (Exception e) {
                conn.rollback(sp);  // rollback to savepoint
                conn.commit();      // commit the rest (if any)
                throw e;
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private User mapRow(ResultSet rs) throws SQLException {
        return new User(rs.getLong("id"), rs.getString("name"), rs.getString("email"));
    }

    record User(long id, String name, String email) {}

    public static void main(String[] args) throws Exception {
        HikariDataSource ds = createPool();
        JdbcPatterns jdbc = new JdbcPatterns(ds);
        Optional<User> user = jdbc.findById(1);
        user.ifPresent(u -> System.out.println(u.name()));
        ds.close();
    }
}

package snippets.java.reactive;

import reactor.core.publisher.*;
import reactor.core.scheduler.Schedulers;
import java.time.Duration;
import java.util.List;

/**
 * Project Reactor — Reactive Programming in Java
 * Used by Spring WebFlux
 */
public class ReactorPatterns {

    record User(Long id, String name) {}

    // ---- Mono (0 or 1 element) ----
    public Mono<User> findUser(Long id) {
        return Mono.fromCallable(() -> new User(id, "Alice"))
            .subscribeOn(Schedulers.boundedElastic()) // offload blocking call
            .timeout(Duration.ofSeconds(5))
            .onErrorReturn(new User(-1L, "Unknown")); // fallback on error
    }

    // ---- Flux (0..N elements) ----
    public Flux<User> findAllUsers() {
        return Flux.fromIterable(List.of(new User(1L,"Alice"), new User(2L,"Bob")))
            .filter(u -> u.id() > 0)
            .map(u -> new User(u.id(), u.name().toUpperCase()))
            .take(10)  // limit
            .delayElements(Duration.ofMillis(10)); // back-pressure demo
    }

    // ---- Combining streams ----
    public Mono<String> mergeData(Long userId, Long orderId) {
        Mono<User>   userMono  = findUser(userId);
        Mono<String> orderMono = Mono.just("Order-" + orderId);
        return Mono.zip(userMono, orderMono,
            (user, order) -> user.name() + " | " + order); // run both in parallel
    }

    // ---- Backpressure ----
    public Flux<Integer> backPressureDemo() {
        return Flux.range(1, 1000)
            .onBackpressureBuffer(100)   // buffer 100 items if slow consumer
            .publishOn(Schedulers.single()) // switch to single thread
            .map(i -> i * 2);
    }

    // ---- Hot vs Cold ----
    // Cold: each subscriber gets full stream from start (default)
    // Hot : stream is ongoing, new subscribers get items from now on
    public static Flux<Long> hotStream() {
        return Flux.interval(Duration.ofSeconds(1)) // hot (interval-based)
            .share(); // multicast to all subscribers
    }

    // ---- Error handling ----
    public Flux<User> robustStream() {
        return Flux.range(1, 5)
            .map(i -> {
                if (i == 3) throw new RuntimeException("DB error");
                return new User((long)i, "User" + i);
            })
            .onErrorContinue((ex, obj) -> System.err.println("Skipping: " + obj))
            // OR: .onErrorResume(ex -> Flux.empty())
            // OR: .retry(3)
            .doOnNext(u -> System.out.println("Processing: " + u.name()))
            .doFinally(sig -> System.out.println("Stream completed: " + sig));
    }

    public static void main(String[] args) throws InterruptedException {
        ReactorPatterns r = new ReactorPatterns();
        r.findUser(1L).subscribe(u -> System.out.println("Found: " + u));
        r.findAllUsers().subscribe(u -> System.out.println(u.name()));
        r.robustStream().blockLast(); // block for demo only
    }
}

package snippets.java.modern;

import java.util.*;
import java.util.stream.*;

/**
 * Modern Java Features (Java 16-21)
 */
public class ModernJavaFeatures {

    // ---- Records (Java 16) ----
    record Point(double x, double y) {
        // Compact constructor for validation
        Point {
            if (Double.isNaN(x) || Double.isNaN(y)) throw new IllegalArgumentException("NaN not allowed");
        }
        // Custom method
        double distanceTo(Point other) {
            return Math.sqrt((x-other.x)*(x-other.x) + (y-other.y)*(y-other.y));
        }
    }

    record PageRequest(int page, int size, String sortBy) {
        // Default constructor built-in canonic constructor
        // Auto-generated: equals, hashCode, toString, getters
    }

    // ---- Sealed Classes (Java 17) ----
    sealed interface Shape permits Circle, Rectangle, Triangle {}
    record Circle(double radius) implements Shape { double area() { return Math.PI*radius*radius; } }
    record Rectangle(double w, double h) implements Shape { double area() { return w*h; } }
    record Triangle(double base, double height) implements Shape { double area() { return 0.5*base*height; } }

    static double getArea(Shape shape) {
        return switch (shape) { // Pattern matching (Java 21 — full)
            case Circle c    -> c.area();
            case Rectangle r -> r.area();
            case Triangle t  -> t.area();
        };
    }

    // ---- Result Type (sealed classes for error handling) ----
    sealed interface Result<T> permits Result.OK, Result.Err {
        record OK<T>(T value) implements Result<T> {}
        record Err<T>(String error, int code) implements Result<T> {}
    }

    static Result<String> divide(int a, int b) {
        if (b == 0) return new Result.Err<>("Division by zero", 400);
        return new Result.OK<>("" + (a / b));
    }

